poly([[37,-21],[50,-17],[76,22],[62,21]],(red?'#ed554b':'#d7a529'));poly([[60,-19],[71,-14],[92,24],[79,23]],(red?'#ed554b':'#e3b02d'));poly([[109,9],[118,10],[130,29],[117,27]],(red?'#ed554b':'#d4a025'));
line(-52,18,129,29,'#758071',1);line(-22,-33,-30,16,'#101b1c',2);
