function worldToScreen(x,y){return{x:(x-camera.x)*viewScale,y:(y-camera.y)*viewScale}}
function screenToWorld(x,y){return{x:x/viewScale+camera.x,y:y/viewScale+camera.y}}
function effects(x,y,n=40,power=1){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,v=Math.random()*180*power;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-30,life:.4+Math.random()*1.2,max:1.6,size:2+Math.random()*12*power,smoke:i%3===0})}rings.push({x,y,r:8,life:.5});shake=Math.max(shake,9*power);beep(70,.4,.12,'sawtooth')}
function damageTank(t,d){damageEnemy(t,d)}
function hurt(d){const h=player();if(h.dead||d<=0)return;h.hp=Math.max(0,h.hp-d*damageReduction());h.hit=.22;shake=Math.max(shake,7);h.vx*=.87;if(selectedVehicle==='heli')h.angle+=.025*h.dir;if(h.hp<=0){h.dead=true;effects(h.x,h.y,140,2.5);const deadCraft=h;setTimeout(()=>{if(mode==='play'&&player()===deadCraft){mode='dead';showResult(false)}},1500)}}
function start(kind='heli'){kind=['heli','tank','engineer','drone'].includes(kind)?kind:selectedVehicle;choiceVehicle=kind;keys={};joy={x:0,y:0};pointer.down=false;shake=0;resetHeli();resetSystems(kind);bullets=[];missiles=[];particles=[];rings=[];tanks=[];kills=0;auto=false;armed=false;radarLeft=0;shotCd=0;missileCd=0;spawnClock=0;mode='play';paused=false;$('modal').hidden=true;$('menu').hidden=true;$('hud').hidden=false;$('pause').style.display='block';const h=player();camera.x=h.x-W*.33/viewScale;camera.y=GROUND-H*.77/viewScale;pointer.x=W*.72;pointer.y=H*.7;toast(selectedVehicle==='drone'?'轻型无人机就绪 · WASD 直接飞行 · 每 25 发耗 1 能量':selectedVehicle==='engineer'?'我方工程装甲车 · 按 B 或筑垒按钮展开推铲':selectedVehicle==='tank'?'重装坦克出击 · 500 耐久 · 升级履带可跨越陡坡':'按住 A/D 持续滑跑后自动起飞；W/S 仅在空中控制升降')}
function openModal(html){$('modalContent').innerHTML=html;$('modal').hidden=false;paused=true;keys={};pointer.down=false;joy={x:0,y:0}}
function closeModal(){if(mode==='dead')return; $('modal').hidden=true;paused=false;$('pause').textContent='Ⅱ 暂停'}
function home(){mode='menu';paused=false;$('menu').hidden=false;$('hud').hidden=true;$('modal').hidden=true;$('pause').style.display='none';keys={};pointer.down=false}
function showResult(win){openModal(`<div class="eyebrow">${win?'区域肃清':'行动结束'}</div><h2>${win?'空域已夺回。':vehicleDisplayName()+'，等待再次出击。'}</h2><p>${win?'所有地面装甲已清除。':'机体失去战斗能力，获得的资金已经保存。可在商店升级后再次出击。'}</p><div class="result-stats">击毁 ${kills} &nbsp; / &nbsp; 资金 ${save.cash}</div><button class="primary" id="retry">再次行动 ↗</button><button class="text-btn" id="returnHome">返回主菜单</button>`);const retryKind=selectedVehicle;$('retry').onclick=()=>start(retryKind);$('returnHome').onclick=home}
function shop(){openModal(`<div class="eyebrow">ARMORY / 整备中心</div><div class="shop-head"><h2>装备与升级</h2><span class="wallet">◈ ${save.cash}</span></div><p>击毁坦克可获得 150 资金。武器与履带最高三级。</p><div class="shop-grid">${shopCard('gun','⌁','机枪伤害',`LV.${save.gun} / 3 · 伤害 ${[0,12,20,30][save.gun]} · 每 5 发耗 1 能量`,save.gun<3?save.gun*300:null)}${shopCard('missile','↗','导弹系统',`LV.${save.missile} / 3 · 伤害 ${MISSILE_DAMAGE[save.missile]} · 爆炸半径 ${MISSILE_RADIUS[save.missile]}${save.missile===3?' · 半追踪':' · 升级解锁橙色条纹与拖尾'}`,save.missile<3?save.missile*400:null)}${shopCard('tracks','▰','坦克综合升级',`LV.${save.tracks} / 3 · 全坡度通行 · 炮伤 ${[0,45,65,90][save.tracks]} · 移速 ${[0,65,78,92][save.tracks]} · 减伤 ${[0,0,15,30][save.tracks]}% · ${['','基础绿','深绿强化炮管','迷彩降低敌方命中'][save.tracks]}`,save.tracks<3?save.tracks*200:null)}${shopCard('repairs','✚','机体修补','立即恢复 50 耐久 · 按 R 使用',120)}${shopCard('radars','◎','战术雷达','60 秒荧光雷达 · 红点敌军 / 绿点我方',100)}</div><p>进度自动保存在本机浏览器。修补道具库存 ${save.repairs} · 雷达库存 ${save.radars}</p>`);document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{let k=b.dataset.buy,cost=+b.dataset.cost;if(save.cash<cost){toast('资金不足，出击摧毁坦克赚取资金');return}if((k==='gun'||k==='missile'||k==='tracks')&&save[k]>=3)return;save.cash-=cost;save[k]++;persist();beep(500,.12);shop()})}
function shopCard(k,symbol,title,desc,cost){return `<div class="shop-item"><span class="symbol">${symbol}</span><small>${cost===null?'MAX LEVEL':'FIELD EQUIPMENT'}</small><h3>${title}</h3><p>${desc}</p><button data-buy="${k}" data-cost="${cost}" ${cost===null?'disabled':''}>${cost===null?'已满级':`${k==='gun'||k==='missile'||k==='tracks'?'升级':'购买'} · ◈ ${cost}`}</button></div>`}
function help(){openModal(`<div class="eyebrow">FLIGHT MANUAL</div><h2>载具操作手册</h2><p>持续按住前进，滑跑加速后自动升空。推荐手机横屏体验；触屏使用左侧摇杆移动，点击战场瞄准，右侧按钮开火。</p><div class="keys"><div><b>A / D</b> 滑跑后自动起飞 · 空中 W/S 升降</div><div><b>鼠标 / 点击战场</b> 黄色虚线瞄准</div><div><b>鼠标按住 / 空格</b> 机枪 · 每 5 发耗 1 能量 / 0.1 秒</div><div><b>F</b> 切换自动射击 · 雷射扫到才开火</div><div><b>Q → 点击目标</b> 导弹 · 25 能量 / 10 秒冷却</div><div><b>G</b> 缓慢收放起落架 · 收起耗能 30</div><div><b>R / E</b> 修补耐久 / 启用 60 秒雷达</div><div><b>Esc</b> 暂停 / 返回</div></div><p>能量上限 100，每秒恢复 1。每次起飞助推耗能 30；持续滑跑速度达到 100 自动离地，无需按 W。按 L 启动自动降落，自动放下起落架并边前进边下降；着陆后冲刺缓冲。手动着陆前完全放下起落架，将下降速度降至 65 以下并保持机身平稳。高速撞地、撞建筑或收轮着陆会严重受损甚至坠机。</p><button class="primary" id="helpDone">明白，准备行动 ↗</button>`);$('helpDone').onclick=closeModal}
function action(a){const heli=player();if(mode!=='play'||paused||heli.dead)return;if(selectedVehicle==='drone'&&['land','gear','missile'].includes(a)){toast('无人机使用 WASD 直接起降，无起落架或导弹');return}if(a==='build'||(a==='land'&&selectedVehicle==='engineer')){buildAlliedFort();return}if(a==='land'){if(selectedVehicle!=='heli'){toast('坦克使用 A/D 移动，升级履带爬坡');return}if(heli.grounded){toast(heli.buffer>0?'降落成功，正在冲刺缓冲中':'已在地面');return}heli.landing=!heli.landing;if(heli.landing){heli.gearTarget=1;heli.landDir=heli.dir;toast('自动降落已启动：放下起落架，保持前进并缓慢下降')}else toast('已取消自动降落');return}if(selectedVehicle!=='heli'&&(a==='gear'||a==='missile')){toast('坦克使用主炮射击，履带可在商店升级');return}if(a==='auto'){auto=!auto;toast(auto?'自动射击已开启：雷射扫中敌人才开火':'自动射击已关闭')}if(a==='gear'){if(heli.grounded&&heli.gearTarget===1){toast('请先升空，再收起起落架');return}if(heli.gearTarget===1){if(heli.energy<30){toast('收起起落架需要 30 能量');return}heli.energy-=30;heli.gearTarget=0;toast('起落架正在收起')}else{heli.gearTarget=1;toast('起落架正在放下：轻缓下降着陆')}}if(a==='missile'){if(missileCd>0){toast(`导弹冷却中，还需 ${Math.ceil(missileCd)} 秒`);return}if(heli.energy<25){toast('导弹需要 25 能量');return}armed=!armed;toast(armed?'导弹就绪：点击战场选择打击位置':'已取消导弹锁定')}if(a==='repair'){if(!save.repairs){toast('修补道具不足，请前往商店购买');return}if(heli.hp>=(heli.max||100)){toast('机体状态完好');return}save.repairs--;heli.hp=Math.min(heli.max||100,heli.hp+50);persist();toast('修补完成：恢复 50 耐久');beep(400,.2,.03,'sine')}if(a==='radar'){if(radarLeft>0){toast('雷达正在工作');return}if(!save.radars){toast('雷达不足，请前往商店购买');return}save.radars--;persist();radarLeft=60;toast('战术雷达已上线，持续 60 秒')}}
function launchMissile(x,y){if(selectedVehicle!=='heli')return;if(missileCd>0||heli.energy<25||heli.dead)return;heli.energy-=25;missileCd=10;armed=false;const target=screenToWorld(x,y);target.x=clamp(target.x,0,WORLD);target.y=clamp(target.y,70,GROUND);let tx=target.x,ty=target.y,lock=enemies().sort((a,b)=>Math.hypot(a.x-tx,a.y-ty)-Math.hypot(b.x-tx,b.y-ty))[0];if(lock&&Math.hypot(lock.x-tx,lock.y-ty)>160)lock=null;let angle=Math.atan2(ty-heli.y,tx-heli.x);missiles.push({x:heli.x+heli.dir*65,y:heli.y+15,vx:Math.cos(angle)*220,vy:Math.sin(angle)*220,tx,ty,lock,life:8,level:save.missile});beep(230,.22,.06,'sawtooth')}
function aim(){const h=player(),p=screenToWorld(pointer.x,pointer.y);if(selectedVehicle==='drone')return droneAim(h,p.x,p.y);if(selectedVehicle!=='heli')return turretAim(h,p.x,p.y);let dx=p.x-h.x,dy=p.y-h.y,a=Math.atan2(dy,dx);return{x:h.x+Math.cos(a)*72,y:h.y+Math.sin(a)*22,a,dx:Math.cos(a),dy:Math.sin(a)}}
function fire(){const h=player();if(shotCd>0||h.dead)return false;const isDrone=selectedVehicle==='drone',tank=!isFlyingVehicle();if(tank){if(h.energy<2)return false;h.energy-=2}else if(!spendShot(h))return false;shotCd=isDrone?shotCd+DRONE_INTERVAL:tank?.65:.1;let a=aim();if(tank||isDrone)h.aimAngle=a.a;bullets.push({x:a.x,y:a.y,vx:a.dx*(tank?950:1050),vy:a.dy*(tank?950:1050),life:tank?2.4:1.6,enemy:false,damage:isDrone?DRONE_DAMAGE:tank?[0,45,65,90][save.tracks]:[0,12,20,30][save.gun],shell:tank,droneShot:isDrone});particles.push({x:a.x,y:a.y,vx:a.dx*40,vy:a.dy*40,life:.045,max:.045,size:isDrone?1.5:tank?16:9,smoke:false});if(!isDrone||Math.random()<.2)beep(isDrone?330:tank?90:180,.035,.012);return true}
function update(dt){const h=player();if(h.dead){updateParticles(dt);return}let ax=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0)+joy.x,ay=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0)+joy.y;ax=clamp(ax,-1,1);ay=clamp(ay,-1,1);shotCd-=dt;missileCd=Math.max(0,missileCd-dt);radarLeft=Math.max(0,radarLeft-dt);
 if(selectedVehicle==='heli')stepFlight(heli,ax,ay,dt);updateSystems(dt,ax,ay);
 camera.x=mix(camera.x,clamp(h.x-W*.33/viewScale,0,WORLD-W/viewScale),Math.min(1,dt*4));camera.y=mix(camera.y,clamp(h.y-H*.48/viewScale,-H/viewScale,GROUND-H*.79/viewScale),Math.min(1,dt*3));
 const a=aim();let lock=null;for(const t of enemies()){let dx=t.x-a.x,dy=t.y-a.y,proj=dx*a.dx+dy*a.dy,dist=Math.abs(dx*a.dy-dy*a.dx);if(proj>0&&proj<1400&&dist<targetRadius(t))lock=t}
 for(const t of tanks){if(t.dead)continue;let delta=h.x-t.x;tankMovement(t,Math.sign(delta),dt,t.traction);t.aimAngle=turretAim(t,h.x,h.y).a;t.cd-=dt;if(Math.abs(delta)<820&&t.cd<0){let off=aimError(h),a=turretAim(t,h.x+off.x,h.y+off.y);t.aimAngle=a.a;bullets.push({x:a.x,y:a.y,vx:a.dx*245,vy:a.dy*245,life:4,enemy:true,damage:9});t.cd=3+Math.random()*2;beep(95,.07,.015)}}
 if(pointer.down||keys[' ']||(auto&&lock)){if(selectedVehicle==='drone'){let shots=0;while(shotCd<=0&&shots++<4)if(!fire())break}else fire()}
 for(const b of bullets){b.px=b.x;b.py=b.y;b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.enemy){if(segmentHit(b.px,b.py,b.x,b.y,h.x-bodyBox(h).rx,h.y-bodyBox(h).ry,bodyBox(h).rx*2,bodyBox(h).ry*2)){hurt(b.damage);b.life=0;impactEffect(b.x,b.y,b.droneShot)}}else for(const t of enemies()){let box=bodyBox(t);if(segmentHit(b.px,b.py,b.x,b.y,t.x-box.rx,t.y-box.ry,box.rx*2,box.ry*2)){damageEnemy(t,b.damage);b.life=0;impactEffect(b.x,b.y,b.droneShot);break}}
  if(b.life>0&&b.y>groundAt(b.x)){for(const f of forts)if(!f.dead&&b.x>=f.x&&b.x<=f.x+f.rise+f.top+f.fall)damageFort(f,b.shell?75:b.damage*.4);b.life=0;b.shell?effects(b.x,groundAt(b.x),18,.5):impactEffect(b.x,groundAt(b.x),b.droneShot)}
 }bullets=bullets.filter(b=>b.life>0);
 for(const m of missiles){const oldX=m.x,oldY=m.y;m.life-=dt;if(m.level===3&&m.lock&&!m.lock.dead){m.tx=mix(m.tx,m.lock.x,dt*3);m.ty=mix(m.ty,m.lock.y,dt*3)}let dx=m.tx-m.x,dy=m.ty-m.y,dist=Math.hypot(dx,dy),speed=Math.min(600,Math.hypot(m.vx,m.vy)+dt*250),angle=Math.atan2(dy,dx);m.vx=mix(m.vx,Math.cos(angle)*speed,dt*(m.level===3?4:2));m.vy=mix(m.vy,Math.sin(angle)*speed,dt*3);m.x+=m.vx*dt;m.y+=m.vy*dt;particles.push({x:m.x,y:m.y,vx:-m.vx*.05,vy:10,life:.35+m.level*.1,max:.7,size:3+m.level,smoke:m.level<3});const target=player(),box=bodyBox(target);let hit=m.enemy?segmentHit(oldX,oldY,m.x,m.y,target.x-box.rx,target.y-box.ry,box.rx*2,box.ry*2):enemies().some(t=>Math.hypot(t.x-m.x,t.y-m.y)<targetRadius(t));if(dist<22||m.y>=groundAt(m.x)||hit||m.life<0){detonateMissile(m);m.life=0}}missiles=missiles.filter(m=>m.life>0);
 updateParticles(dt);shake*=Math.exp(-dt*11);spawnClock+=dt;$('missionText').textContent='持续生存 · 敌方工程车持续增援';updateHud();}
function detonateMissile(m){if(m.enemy){const h=player(),d=Math.hypot(h.x-m.x,h.y-m.y);effects(m.x,m.y,45,1.1);if(d<130)hurt(30*(1-.5*d/130));for(const f of forts)if(f.allied&&!f.dead&&Math.abs(f.x+f.rise-m.x)<180)damageFort(f,45);return}const radius=MISSILE_RADIUS[m.level];effects(m.x,m.y,100,2.2);rings.push({x:m.x,y:m.y,r:radius*.65,life:.45});for(const t of enemies()){const d=Math.hypot(t.x-m.x,t.y-m.y);if(d<radius)damageEnemy(t,MISSILE_DAMAGE[m.level]*(1-.55*d/radius))}for(const f of forts)if(!f.dead&&Math.abs(f.x+f.rise-m.x)<radius+f.top)damageFort(f,MISSILE_DAMAGE[m.level]);}
function segmentHit(x1,y1,x2,y2,x,y,w,h){let min=0,max=1,dx=x2-x1,dy=y2-y1;for(const [p,q] of [[-dx,x1-x],[dx,x+w-x1],[-dy,y1-y], [dy,y+h-y1]]){if(p===0){if(q<0)return false}else{let r=q/p;if(p<0)min=Math.max(min,r);else max=Math.min(max,r);if(min>max)return false}}return true}
function updateParticles(dt){for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=(p.smoke?-5:p.ember?12:100)*dt;p.vx*=Math.exp(-dt*2)}particles=particles.filter(p=>p.life>0).slice(-700);for(const r of rings){r.r+=dt*(r.speed||260);r.life-=dt}rings=rings.filter(r=>r.life>0)}
function updateHud(){const heli=player(),max=heli.max||100;$('hpText').textContent=`${Number(heli.hp.toFixed(1))} / ${max}`;$('energyText').textContent=`${Math.floor(heli.energy)} / 100`;$('hpBar').style.width=heli.hp/max*100+'%';$('energyBar').style.width=heli.energy+'%';$('flightState').textContent=selectedVehicle==='drone'?'无人机巡航':selectedVehicle!=='heli'?(heli.blocked?'履带打滑':selectedVehicle==='engineer'?'工程装甲车':'重装坦克'):heli.buffer>0?'冲刺缓冲中':heli.landing?'自动降落中':heli.grounded?(Math.abs(heli.vx)>2?'滑跑加速':'停机待命'):heli.gear>.2?'起落架展开':'空中巡航';$('kills').textContent=String(kills).padStart(2,'0');$('cash').textContent=save.cash;$('autoBtn').classList.toggle('active',auto);$('autoBtn').querySelector('small').textContent=auto?'雷射触发':'关闭';$('missileBtn').classList.toggle('active',armed);$('missileBtn').querySelector('small').textContent=armed?'点击目标':missileCd>0?Math.ceil(missileCd)+' 秒':'25 能量';$('gearBtn').querySelector('small').textContent=heli.gearTarget===1?(heli.gear<.98?'正在放下':'已放下'):(heli.gear>.02?'正在收起':'已收起');$('repairBtn').querySelector('small').textContent='× '+save.repairs;$('radarBtn').querySelector('small').textContent=radarLeft>0?Math.ceil(radarLeft)+' 秒':'× '+save.radars;$('radar').style.display=radarLeft>0?'block':'none';$('landingBtn').classList.toggle('active',!!heli.landing);$('landingBtn').disabled=selectedVehicle==='drone';$('landingBtn').querySelector('small').textContent=selectedVehicle==='drone'?'直接起降':selectedVehicle==='engineer'?(heli.building&&heli.building.progress<1?'施工中':'推铲就绪'):selectedVehicle==='tank'?'地面载具':heli.landing?'下降中':heli.buffer>0?'缓冲中':'自动放轮';$('landingBtn').querySelector('span').textContent=selectedVehicle==='engineer'?'推铲筑垒':'降落系统';$('missileBtn').disabled=selectedVehicle!=='heli';$('gearBtn').disabled=selectedVehicle!=='heli';$('hint').textContent=selectedVehicle==='drone'?'WASD 直接飞行 · 枪口雷射瞄准 · 每发 0.1 伤害 · 每 25 发耗 1 能量':selectedVehicle==='engineer'?'A/D 移动 · 鼠标/空格开火 · B 或筑垒按钮部署推铲':selectedVehicle==='tank'?'A/D 移动 · 鼠标/空格主炮 · 商店升级履带、火力与装甲':'A/D 持续滑跑自动起飞 · 空中 W/S 升降 · L 自动降落 · 每 5 发耗 1 能量';$('unitName').textContent=selectedVehicle==='drone'?'U-35':selectedVehicle==='engineer'?'E-350':selectedVehicle==='tank'?'T-500':'D-72FE';if(radarLeft>0)drawRadar()}
function drawRadar(){const heli=player();const r=$('radarCanvas').getContext('2d');r.fillStyle='#071b12';r.fillRect(0,0,190,150);r.strokeStyle='#40945f30';r.lineWidth=1;for(let i=0;i<190;i+=25){r.beginPath();r.moveTo(i,0);r.lineTo(i,150);r.stroke()}for(let i=0;i<150;i+=25){r.beginPath();r.moveTo(0,i);r.lineTo(190,i);r.stroke()}r.save();r.translate(95,75);r.rotate(time*1.5);let g=r.createConicGradient(-.8,0,0);g.addColorStop(0,'#5bff9030');g.addColorStop(.14,'#5bff9000');r.fillStyle=g;r.beginPath();r.arc(0,0,90,0,Math.PI*2);r.fill();r.restore();for(const t of enemies()){let x=95+(t.x-heli.x)/15,y=75+(t.y-heli.y)/7;if(x>0&&x<190){r.fillStyle='#ff6557';r.beginPath();r.arc(x,clamp(y,5,145),2.5,0,7);r.fill()}}r.fillStyle='#8bffac';r.beginPath();r.arc(95,75,3,0,7);r.fill();$('radarTime').textContent='RADAR ACTIVE / '+Math.ceil(radarLeft)+'s'}
function drawWorld(){ctx.save();ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);ctx.scale(viewScale,viewScale);ctx.translate(-camera.x,-camera.y);let left=camera.x-100,right=camera.x+W/viewScale+100;
rect(left,GROUND,right-left,800,'#182523');rect(left,GROUND,right-left,7,'#7d8063');rect(left,GROUND+7,right-left,13,'#374233');for(let x=Math.floor(left/150)*150;x<right;x+=150){rect(x+10,GROUND+50,64,4,'#b2a15f32');poly([[x+20,GROUND],[x+45,GROUND-12],[x+61,GROUND],[x+75,GROUND+8]],'#3e4939');line(x,GROUND+30,x+65,GROUND+20,'#0d1b1b',2)}
drawTerrain(left,right);
// Runway markings and landing pad.
rect(200,GROUND,560,6,'#a8a387');for(let x=220;x<760;x+=70)rect(x,GROUND+22,40,5,'#b2a26c');ctx.fillStyle='#b5a96b80';ctx.font='24px monospace';ctx.fillText('07 — LANDING ZONE',245,GROUND+75);
for(const b of buildings){if(b.x+b.w<left||b.x>right)continue;poly([[b.x,GROUND],[b.x,GROUND-b.h],[b.x+b.w*.38,GROUND-b.h+7],[b.x+b.w*.52,GROUND-b.h-8],[b.x+b.w*.63,GROUND-b.h+14],[b.x+b.w,GROUND-b.h+9],[b.x+b.w,GROUND]],'#283733','#71806b',1);for(let j=0;j<4;j++)rect(b.x+13+j*32,GROUND-b.h+22,13,20,'#111f23');rect(b.x+8,GROUND-27,b.w-16,8,'#a4934a40');for(let j=0;j<3;j++)line(b.x+13+j*20,GROUND-b.h+5,b.x+21+j*20,GROUND-b.h-15,'#586a59',2)}
for(const t of tanks)if(t.x>left&&t.x<right){if(!t.dead)drawTank(t);else{poly([[t.x-43,GROUND],[t.x-35,GROUND-23],[t.x+25,GROUND-20],[t.x+45,GROUND]],'#192320');circle(t.x,GROUND-14,9,'#c775211e')}}
drawSystems();
if(!player().dead){let a=aim();ctx.save();ctx.setLineDash(armed?[10,6]:[5,8]);ctx.lineDashOffset=-time*20;ctx.globalAlpha=.65;line(a.x,a.y,a.x+a.dx*1350,a.y+a.dy*1350,armed?'#ff973e':'#fbe264',1);ctx.restore();if(armed){let p=screenToWorld(pointer.x,pointer.y);circle(p.x,p.y,23,null,'#ffb65d');line(p.x-35,p.y,p.x+35,p.y,'#ffb65d');line(p.x,p.y-35,p.x,p.y+35,'#ffb65d')}if(selectedVehicle==='heli')drawHeli(heli.x,heli.y,1,heli.angle,heli.gear,heli.flip);if(selectedVehicle==='heli'&&heli.hit>0){ctx.globalAlpha=heli.hit;circle(heli.x,heli.y,75,'#ff9b4f');ctx.globalAlpha=1}}
for(const b of bullets){ctx.shadowColor=b.enemy?'#f86f42':'#ffb02e';ctx.shadowBlur=10;line(b.x,b.y,b.x-b.vx*.017,b.y-b.vy*.017,b.enemy?'#eb7e54':'#ffaf37',b.enemy?3:2.5);ctx.shadowBlur=0}
for(const m of missiles){ctx.save();ctx.translate(m.x,m.y);ctx.scale(1.65,1.65);ctx.rotate(Math.atan2(m.vy,m.vx));let fl=16+m.level*5;poly([[-12,-4],[-12-fl*(.8+Math.random()*.3),0],[-12,4]],'#ff7f25');poly([[-13,-2],[-13-fl*.6,0],[-13,2]],'#fff8a1');poly([[-14,-4],[10,-4],[18,0],[10,4],[-14,4]],m.enemy?'#edba57':'#f2d34b','#8f7a36');if(m.level>1){rect(-7,-4,m.level===3?6:3,8,'#f58d27');rect(2,-4,m.level===3?6:3,8,'#f58d27')}poly([[-12,-3],[-18,-10],[-7,-4]],'#9c9a6a');poly([[-12,3],[-18,10],[-7,4]],'#9c9a6a');ctx.restore()}
for(const p of particles){let a=clamp(p.life/p.max,0,1);ctx.globalAlpha=a;if(p.smoke){ctx.globalAlpha=a*(p.alpha||.32);if(p.block){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rotation||0);const r=p.size;poly([[-r,-r*.7],[r*.7,-r],[r,r*.5],[-r*.6,r]],'#3e4245');ctx.restore()}else{ctx.save();ctx.translate(p.x,p.y);ctx.scale(1.45,1);circle(0,0,p.size*(1.3-a*.3),'#8d9092');ctx.restore()}}else{ctx.globalCompositeOperation='lighter';circle(p.x,p.y,p.size*a,a>.5?'#ffb33f':'#e66c25');ctx.globalCompositeOperation='source-over'}ctx.globalAlpha=1}
for(const r of rings){ctx.globalAlpha=r.life*1.5;ctx.lineWidth=2;circle(r.x,r.y,r.r,null,'#ffe9a1');ctx.globalAlpha=1}ctx.restore()}
function frame(now){let dt=Math.min(.033,(now-last)/1000||.016);last=now;time+=dt;if(performance.now()>toastUntil)$('toast').style.opacity='0';ctx.setTransform(dpr,0,0,dpr,0,0);if(mode==='menu'){camera.x=time*9;background(true);let mobile=W<761,s=mobile?Math.min(W/530,.9):Math.min(W/880,H/560);let x=mobile?W*.58:W*.74,y=mobile?H*.64:H*.47;ctx.save();ctx.globalAlpha=.2;ctx.translate(x,H*.84);ctx.scale(1,.15);circle(0,0,140*s,'#040d12');ctx.restore();drawHeli(x,y+Math.sin(time)*5,s,-.065,.5+.5*Math.sin(time*.6),1,true);if(!mobile){ctx.strokeStyle='#c2c7a817';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,230*s,-1.6,1.5);ctx.stroke();line(x-80*s,y+80*s,x-20*s,y+130*s,'#d1b94c50');line(x-20*s,y+130*s,x+110*s,y+130*s,'#d1b94c50')}}else{if(!paused&&mode==='play')update(dt);background();drawWorld()}renderSelectionPreview();requestAnimationFrame(frame)}requestAnimationFrame(frame);
