addEventListener('keydown',e=>{if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();let k=e.key.length===1?e.key.toLowerCase():e.key;if(k==='Escape'){if(!$('modal').hidden)closeModal();else if(mode==='play')$('pause').click();return}if(e.repeat)return;keys[k]=true;const map={f:'auto',q:'missile',g:'gear',r:'repair',e:'radar',l:'land',b:'build'};if(map[k])action(map[k])});addEventListener('keyup',e=>{keys[e.key.length===1?e.key.toLowerCase():e.key]=false});addEventListener('blur',()=>{keys={};pointer.down=false;joy={x:0,y:0};if(mode==='play'&&!paused)$('pause').click()});
canvas.addEventListener('pointermove',e=>{pointer.x=e.clientX;pointer.y=e.clientY});canvas.addEventListener('pointerdown',e=>{if(mode!=='play'||paused)return;pointer.x=e.clientX;pointer.y=e.clientY;if(armed){launchMissile(e.clientX,e.clientY);return}if(e.pointerType!=='touch'){pointer.down=true;canvas.setPointerCapture(e.pointerId)}});canvas.addEventListener('pointerup',()=>pointer.down=false);canvas.addEventListener('pointercancel',()=>pointer.down=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());
const joystick=$('joystick');let joyPointer=null;function moveJoy(e){const r=joystick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,l=Math.hypot(dx,dy),max=r.width*.34;joy.x=dx/Math.max(l,max);joy.y=dy/Math.max(l,max);$('stick').style.transform=`translate(${joy.x*max}px,${joy.y*max}px)`}
joystick.onpointerdown=e=>{joyPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);moveJoy(e)};joystick.onpointermove=e=>{if(e.pointerId===joyPointer)moveJoy(e)};joystick.onpointerup=joystick.onpointercancel=()=>{joyPointer=null;joy={x:0,y:0};$('stick').style.transform=''};$('touchFire').onpointerdown=e=>{e.preventDefault();if(mode==='play'&&!paused){pointer.down=true;$('touchFire').setPointerCapture(e.pointerId)}};$('touchFire').onpointerup=$('touchFire').onpointercancel=()=>pointer.down=false;
