function impactEffect(x,y,small=false){const count=small?2:3;for(let i=0;i<count;i++)particles.push({x,y,vx:(Math.random()-.5)*35,vy:-15-Math.random()*20,life:.12,max:.12,size:small?1:2,smoke:false});rings.push({x,y,r:small?1.5:2.5,life:.12,speed:small?25:40})}
